// The field notebook: one page for each idea, opened by finishing the level that teaches it.
// Every page: a name, a few plain sentences, who worked the idea out and when (checked against a reliable source), and a small drawing (js/ui/draw.js).
export const CARDS = {
  loss: { name: 'Loss', draw: 'loss',
    text: ['A machine that is learning keeps one number that says how wrong it is. That number is called the loss.', 'In this game the loss is height. The higher Theta stands, the worse the guess. Every level ends on the lowest ground there is.'] },
  gradient: { name: 'Gradient', draw: 'gradient',
    text: ['The gradient is the slope under your feet. It tells you two things at once: which way is down, and how steep it is.', 'Theta cannot see the whole valley from here, and does not need to. The ground underfoot is enough to choose the next step.'] },
  rate: { name: 'Learning rate', draw: 'rate',
    text: ['How far to go on each step is a choice, and it has a name: the learning rate.', 'Short steps are safe and slow. Long steps cover ground, as long as there is room to land.', 'Eta, the firefly, is named for the Greek letter η, which is how the learning rate is usually written.'] },
  overshoot: { name: 'Overshoot', draw: 'overshoot',
    text: ['Take too long a step into a narrow valley and you land on the far wall, higher than where you started.', 'Do it again and you can climb right out. When the learning rate is too high, the loss goes up when it should go down.'] },
  descent: { name: 'Gradient descent', draw: 'descent', who: 'Augustin-Louis Cauchy, 1847',
    text: ['Look at the slope. Take a step downhill. Look again.', 'That is the whole method, and it is called gradient descent. Augustin-Louis Cauchy, a French mathematician, described it in 1847. Most machines that learn today are still trained this way.'],
    math: 'θ ← θ − η ∇L(θ)', key: 'θ is where you stand, η is the length of the step, and ∇L(θ) is the slope there.' },
  // ---- Cappadocia ----
  momentum: { name: 'Momentum', draw: 'momentum', who: 'Boris Polyak, 1964',
    text: ['A ball rolling downhill does not forget how fast it was going. It carries some of that speed into the next stretch of ground.', 'Plain gradient descent has no such memory: it steps, stops and looks again. In 1964 the mathematician Boris Polyak gave it one, and compared the result to a heavy ball rolling. The remembered speed is called momentum.', 'Mu, the bird, is named for the Greek letter μ, which is how momentum is usually written.'],
    math: 'v ← μv − η ∇L(θ),   θ ← θ + v', key: 'v is the speed carried over from before, and μ says how much of it to keep.' },
  local: { name: 'Local minimum', draw: 'local',
    text: ['A hollow is the lowest ground nearby. It is not the lowest ground there is.', 'A walker who only ever steps downhill stops in the first hollow and thinks the journey is over. Such a place is called a local minimum.'] },
  carry: { name: 'Over the rim', draw: 'momentum',
    text: ['Speed gained on the way down can carry you over the rim of a hollow and on toward lower ground.', 'That is what momentum is for. If you stop in a hollow, go back up the way you came and take a run at it.'] },
  start: { name: 'Where you start', draw: 'start',
    text: ['Two travellers who set out from different places can finish in different valleys, even if both always go downhill.', 'So where you start matters. When nobody knows the best place to begin, people try several starts and keep the one that ends lowest.'] },
  heavy: { name: 'Too much momentum', draw: 'overshoot',
    text: ['Keep too much speed and you sail past the valley you wanted and have to come back for it.', 'So μ is kept a little under 1. A value of 0.9 is a common choice: nine tenths of the old speed is kept on every step.'] },
  // ---- Galápagos ----
  batch: { name: 'A handful at a time', draw: 'batch',
    text: ['To know the slope exactly, a machine would have to look at every example it has been given, and there may be millions.', 'So it looks at a handful, picked by chance, and takes the slope from those. The handful is called a batch.'] },
  noise: { name: 'A noisy slope', draw: 'noisy',
    text: ['A handful never tells the whole truth. The slope it gives is a little off, and off in a different way each time.', 'The steps wobble, as a raft does on the swell. On average they still go downhill.'] },
  sgd: { name: 'Stochastic gradient descent', draw: 'noisy', who: 'Herbert Robbins and Sutton Monro, 1951',
    text: ['Taking every step from a chance handful is called stochastic gradient descent. Stochastic means governed by chance.', 'In 1951 Herbert Robbins and Sutton Monro showed that a method fed on noisy measurements still arrives, as long as its steps grow smaller as it goes.'],
    math: 'θ ← θ − η ∇L_B(θ)', key: 'L_B is the loss measured on one handful, B, of the examples.' },
  shake: { name: 'Shaken loose', draw: 'local',
    text: ['The wobble is not only a nuisance. A noisy step can lift a traveller out of a shallow hollow that an exact step would never leave.', 'The tide does the same for Theta here: it comes in, and what was a trap is a way out.'] },
  settle: { name: 'Settling', draw: 'descent',
    text: ['Near the bottom, the same wobble keeps you from ever standing still.', 'Smaller steps quiet it, and so do bigger handfuls. Many training runs shorten their steps toward the end for this reason.'] },
  // ---- Namib ----
  plateau: { name: 'Plateau', draw: 'plateau',
    text: ['On level ground the slope is nearly nothing, and it says nearly nothing about which way to go.', 'Learning slows to a crawl in such places. They are called plateaus, and the loss can sit on one for a long time before it starts to fall again.'] },
  patience: { name: 'Keep going', draw: 'plateau',
    text: ['A plateau is not the bottom. It only feels like one.', 'Speed carried in from the last slope will take you a long way across level ground. It is one more reason machines are given momentum.'] },
  schedule: { name: 'A schedule for the steps', draw: 'rate',
    text: ['The best length of step is not the same all the way down. Long steps suit the start, when the valley is far off. Short ones suit the end, when it is underfoot.', 'A plan for changing the learning rate as training goes on is called a schedule.'] },
  decay: { name: 'Shorter and shorter', draw: 'descent',
    text: ['The commonest schedule simply shrinks the step as time passes, a little at a time or all at once every so often.', 'The dunes here do it for you. Each is lower than the last, and the final ones can be taken at a walk.'] },
  warmup: { name: 'Warming up', draw: 'noisy',
    text: ['Some schedules also begin small. At the very start a machine knows nothing, the slopes it measures are wild, and a long step taken on bad advice does harm.', 'So the steps start short, grow for a while, and only then begin to shrink. The growing part is called warm-up.'] },
  // ---- Zhangjiajie ----
  ravine: { name: 'Ravine', draw: 'overshoot',
    text: ['A ravine is a valley that is steep from side to side and nearly level along its floor.', 'The way on runs along the floor. The slope underfoot points at the walls.'] },
  zigzag: { name: 'Side to side', draw: 'overshoot',
    text: ['Follow the slope in a ravine and you cross the floor, climb the far wall, turn, and cross again.', 'Each crossing gains only a little ground along the valley. Plain gradient descent spends most of its effort going from side to side.'] },
  adaptive: { name: 'A step for each direction', draw: 'rate', who: 'John Duchi, Elad Hazan and Yoram Singer, 2011',
    text: ['The cure is to stop using one length of step for every direction.', 'Take short steps across the ravine, where the ground is steep, and long ones along it, where it is nearly level. A method called AdaGrad, published in 2011 by John Duchi, Elad Hazan and Yoram Singer, does this by keeping count of how steep each direction has been.'] },
  rms: { name: 'Recent memory', draw: 'noisy', who: 'Geoffrey Hinton, 2012',
    text: ['AdaGrad remembers every slope it has ever met, so its steps only ever shrink, and in a long run they shrink to nothing.', 'RMSProp, which Geoffrey Hinton described in his lectures in 2012, keeps a fading memory instead: recent slopes count, and old ones are forgotten.'] },
  adam: { name: 'Adam', draw: 'descent', who: 'Diederik Kingma and Jimmy Ba, 2014',
    text: ['Adam does both at once. It carries momentum, and it sets a step for each direction from recent memory.', 'Diederik Kingma and Jimmy Ba published it in 2014. A great many of today’s models are trained with it, or with something built on it.'],
    math: 'θ ← θ − η · m / (√v + ε)', key: 'm is a running average of the slope, and v a running average of its square: how steep each direction has lately been.' },
  chain: { name: 'Link by link', draw: 'chain', who: 'David Rumelhart, Geoffrey Hinton and Ronald Williams, 1986',
    text: ['A deep network is a long chain of layers. To learn, each layer has to be told how much it had to do with the error at the far end.', 'The answer is passed back along the chain, and at every link it is multiplied by a number. The method is called backpropagation. David Rumelhart, Geoffrey Hinton and Ronald Williams made it widely known in 1986.'] },
  explode: { name: 'Too much', draw: 'explode',
    text: ['Multiply by a number a little larger than one, many times over, and the result is enormous.', 'A signal that grows at every link arrives too large to use. The step it calls for throws the model far from anywhere it has been. This is an exploding gradient.'] },
  vanish: { name: 'Almost nothing', draw: 'vanish', who: 'Sepp Hochreiter, 1991',
    text: ['Multiply by a number a little smaller than one, many times over, and almost nothing is left.', 'The layers furthest from the error hear only a whisper, and barely learn. Sepp Hochreiter described this vanishing gradient in 1991. It held deep networks back for years.'] },
  clip: { name: 'A limit', draw: 'clip', who: 'Razvan Pascanu, Tomas Mikolov and Yoshua Bengio, 2013',
    text: ['One cure for a signal that is too large is plain: set a limit. If the slope calls for a step longer than the limit, take a step of the limit’s length, in the same direction.', 'This is gradient clipping. Razvan Pascanu, Tomas Mikolov and Yoshua Bengio set it out in 2013.'] },
  skip: { name: 'The short way', draw: 'skip', who: 'Kaiming He, Xiangyu Zhang, Shaoqing Ren and Jian Sun, 2015',
    text: ['Another cure is to give the signal a way round. A skip connection carries it past a group of layers untouched, so it arrives whole however long the chain.', 'Kaiming He, Xiangyu Zhang, Shaoqing Ren and Jian Sun built networks this way in 2015, and trained ones more than a hundred layers deep.'] },
};
